OPERATION retry fail_now and propagate skipped downstream
INPUT {
  "name": "demo-failure",
  "tasks": [
    {
      "id": "bad",
      "task_type": "fail_now",
      "max_attempts": 3,
      "retry_delay_seconds": 0.2,
      "args": {}
    },
    {
      "id": "downstream",
      "task_type": "value",
      "depends_on": [
        "bad"
      ],
      "args": {
        "ref": "bad"
      }
    }
  ]
}
API_RESPONSE {
  "run_id": "demo-failure",
  "status": "failed",
  "results": {
    "bad": {
      "status": "failed",
      "attempts": 3,
      "output": null,
      "error": {
        "code": "BUILTIN_TASK_FAILED",
        "message": "任务 'bad' 按定义失败（fail_now）"
      }
    },
    "downstream": {
      "status": "skipped",
      "attempts": 0,
      "output": null,
      "error": null
    }
  }
}
